<?php require_once __DIR__.'/../../includes/auth.php';requireSuperAdmin();require_once __DIR__.'/../../includes/functions.php';$events=$pdo->query("SELECT id,name,event_code,status FROM events ORDER BY created_at DESC")->fetchAll();$pageTitle='Categories';require __DIR__.'/../../includes/header.php';require __DIR__.'/../../includes/sidebar.php';?><main class="main"><?php require __DIR__.'/../../includes/topbar.php';?><section class="content"><?php showFlash();?><div class="mb-4"><span class="section-kicker">EVENT MANAGEMENT</span><h1 class="page-title">Categories</h1><p class="page-subtitle">Choose an event to manage its categories.</p></div><div class="row g-3"><?php foreach($events as $e):?><div class="col-xl-4 col-md-6"><div class="panel h-100"><div class="panel-body"><div class="d-flex justify-content-between"><div><h5><?=e($e['name'])?></h5><div class="text-muted small"><?=e($e['event_code'])?></div></div><span class="badge-soft badge-<?=strtolower($e['status'])?>"><?=e($e['status'])?></span></div><a class="btn btn-primary w-100 mt-4" href="index.php?event_id=<?=$e['id']?>">Manage Categories</a></div></div></div><?php endforeach;if(!$events):?><div class="col-12"><div class="empty-state"><h5>No events</h5><p>Create an event first.</p><a class="btn btn-primary" href="../events/create.php">Create Event</a></div></div><?php endif;?></div></section></main><?php require __DIR__.'/../../includes/footer.php';?>
